	const binary = Array.from(bytes)
		.map((b) => String.fromCharCode(b))
		.join("");
	return btoa(binary);
}

function base64ToUint8Array(base64: string): Uint8Array {
	const binary = atob(base64);
	return Uint8Array.from(binary, (c) => c.charCodeAt(0));
